// Arguments that are plain data when the call starts, which the load's own
// code changes while the call reads what comes before them: options that
// name a zone, removed by a getter and by a member's conversion to a
// string, so the call takes the machine's zone; and a list of tags that the
// compared value's conversion empties, so the comparison takes the default
// locale.
var removing = {
  timeZone: "Asia/Tokyo",
  get hour12() {
    delete this.timeZone;
    return false;
  },
};
var byGetter = new Intl.DateTimeFormat("en-US", removing).resolvedOptions().timeZone;
var converting = { timeZone: "Asia/Tokyo" };
converting.calendar = {
  toString: function () {
    delete converting.timeZone;
    return "gregory";
  },
};
var byConversion = new Intl.DateTimeFormat("en-US", converting).resolvedOptions().timeZone;
var emptied = ["de-DE"];
var compared = {
  toString: function () {
    emptied.length = 0;
    return "z";
  },
};
module.exports = {
  byGetter: byGetter,
  byConversion: byConversion,
  order: "ä".localeCompare(compared, emptied),
};
